import json, collections
from pathlib import Path
B = Path(__file__).resolve().parent
res = {q["id"]: q for q in json.load(open(B/"results.json"))}
key = json.load(open(B/"key.json"))
ver = json.load(open(B/"verdicts.json"))
tally = collections.Counter()
lines = ["| # | query | old first row | new first row | verdict | reason |", "|--|--|--|--|--|--|"]
worse = []
def row(r):
    return f"{r['file']}:{r['l0']} {r['kind']} {(r['sig'] or '')[:50]}"
for i, k in key.items():
    q = res[k["id"]]
    v, why = ver[i]
    if v == "equal":
        o = "equal"
    else:
